-- Read-only exact QA admin schema; no row data, credentials or Auth identities.
select jsonb_build_object('functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='admin_ops' or n.nspname='public' and (p.proname like 'triniti_%admin%' or p.proname in ('update_comment_count','sync_post_comment_count','sync_post_comments_count','admin_support_triage_read','admin_support_triage_update','admin_seller_review_reports','moderate_seller_review'))),'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'acl',c.relacl::text,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(pg_get_constraintdef(oid) order by conname) from pg_constraint where conrelid=c.oid and contype<>'n'),'indexes',(select jsonb_agg(indexdef order by indexname) from pg_indexes where schemaname='admin_ops' and tablename=c.relname)) order by c.relname) from pg_class c where c.relnamespace=to_regnamespace('admin_ops') and c.relkind='r'),'triggers',(select jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) order by t.tgname,t.tgrelid::regclass::text) from pg_trigger t join pg_proc p on p.oid=t.tgfoid where not t.tgisinternal and p.pronamespace=to_regnamespace('admin_ops')),'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname in ('admin_ops') or schemaname='public' and tablename in ('verification_applications','user_reports','admin_users','admin_audit_log')),'preserved_counts',jsonb_build_object('auth_users',(select count(*) from auth.users),'admin_users',(select count(*) from public.admin_users),'profiles',(select count(*) from public.profiles),'storage_objects',(select count(*) from storage.objects))) catalog;
